BEGIN;
SELECT set_config('request.jwt.claim.sub','b2f6e43d-ce24-4de2-a770-0548793cc180',true);
SET LOCAL ROLE authenticated;
DO $$DECLARE rid uuid; r public.finance_recurring_expenses; payload jsonb; first_on date:=current_date; ids uuid[]; n integer; paid_id uuid; custom_id uuid; excluded_id uuid;BEGIN
 payload:=jsonb_build_object('description','Recorrência teste rollback','amount_cents',10000,'frequency','monthly','start_on',first_on);
 rid:=public.save_finance_recurrence(payload);
 SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 SELECT array_agg(id ORDER BY occurrence_on),count(*) INTO ids,n FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND deleted_at IS NULL;
 IF n<12 THEN RAISE EXCEPTION 'Previsão não foi gerada';END IF;
 PERFORM public.sync_finance_recurrences(NULL,rid);
 IF (SELECT count(*) FROM public.enterprise_finance_accounts WHERE recurrence_id=rid)<>n THEN RAISE EXCEPTION 'Recorrência duplicada na sincronização';END IF;
 paid_id:=ids[1];custom_id:=ids[2];excluded_id:=ids[3];
 UPDATE public.enterprise_finance_accounts SET settled_on=current_date WHERE id=paid_id;
 UPDATE public.enterprise_finance_accounts SET amount_cents=12345 WHERE id=custom_id;
 IF NOT (SELECT recurrence_overridden FROM public.enterprise_finance_accounts WHERE id=custom_id) THEN RAISE EXCEPTION 'Edição individual não marcada';END IF;
 UPDATE public.enterprise_finance_accounts SET deleted_at=now() WHERE id=excluded_id;
 PERFORM public.save_finance_recurrence(payload||jsonb_build_object('amount_cents',20000),rid,r.updated_at,current_date);
 IF (SELECT amount_cents FROM public.enterprise_finance_accounts WHERE id=paid_id)<>10000 THEN RAISE EXCEPTION 'Conta paga foi alterada';END IF;
 IF (SELECT amount_cents FROM public.enterprise_finance_accounts WHERE id=custom_id)<>12345 THEN RAISE EXCEPTION 'Ajuste individual perdido';END IF;
 IF (SELECT amount_cents FROM public.enterprise_finance_accounts WHERE id=ids[4])<>20000 THEN RAISE EXCEPTION 'Próximas não foram atualizadas';END IF;
 SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 PERFORM public.set_finance_recurrence_active(rid,r.updated_at,false);
 IF EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND settled_on IS NULL AND occurrence_on>=current_date AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Pausa manteve futuros em aberto';END IF;
 IF (SELECT deleted_at FROM public.enterprise_finance_accounts WHERE id=paid_id) IS NOT NULL THEN RAISE EXCEPTION 'Pausa excluiu conta paga';END IF;
 SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 PERFORM public.set_finance_recurrence_active(rid,r.updated_at,true);
 IF (SELECT deleted_at FROM public.enterprise_finance_accounts WHERE id=custom_id) IS NOT NULL OR (SELECT amount_cents FROM public.enterprise_finance_accounts WHERE id=custom_id)<>12345 THEN RAISE EXCEPTION 'Reativação perdeu ajuste';END IF;
 IF (SELECT deleted_at FROM public.enterprise_finance_accounts WHERE id=excluded_id) IS NULL THEN RAISE EXCEPTION 'Reativação recriou exclusão individual';END IF;
 PERFORM public.save_finance_recurrence(payload||jsonb_build_object('end_on',first_on),rid,r.updated_at,current_date);
 IF EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND occurrence_on>first_on AND settled_on IS NULL AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Término deixou contas futuras';END IF;
 IF public.finance_recurrence_due('2026-01-31','monthly',2)<>'2026-03-31'::date OR public.finance_recurrence_due('2028-01-31','monthly',1)<>'2028-02-29'::date OR public.finance_recurrence_due('2026-12-20','fortnightly',1)<>'2027-01-04'::date THEN RAISE EXCEPTION 'Calendário incorreto';END IF;
END $$;
SELECT set_config('request.jwt.claim.sub','a6fd10de-33d6-45c3-b423-9290dad107ea',true);
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM public.finance_recurring_expenses) THEN RAISE EXCEPTION 'Colaborador leu recorrências';END IF;
 BEGIN PERFORM public.save_finance_recurrence('{}');RAISE EXCEPTION 'Colaborador criou recorrência';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sync_finance_recurrences();RAISE EXCEPTION 'Colaborador executou sincronização';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;ROLLBACK;
SELECT 'PASS: calendário, geração sem duplicação, baixa preservada, ajuste/exclusão individual, pausa/reativação/término e RLS; rollback completo' result;
